const jobs = [
  ['Junior Data Engineer','Northstar Data','Ankara','https://www.linkedin.com/jobs/view/900000001/?trackingId=mock-1','Python SQL ETL data pipelines. 0-2 years.'],
  ['Python Backend Developer','Bosporus Labs','İstanbul','https://www.linkedin.com/jobs/view/python-backend-900000002/?refId=mock-2','Python FastAPI PostgreSQL Docker REST API. 1-2 years.'],
  ['Machine Learning Engineer','Vision Works','İstanbul','https://www.linkedin.com/jobs/view/900000003/?trackingId=mock-3','Python PyTorch machine learning. 5+ years required.'],
  ['Data Analyst','Aegean Analytics','İzmir','https://www.linkedin.com/jobs/view/900000004/?trk=mock-4','SQL Python pandas analytics. Entry level.'],
  ['Software Engineer','Anatolia Software','Ankara','https://www.linkedin.com/jobs/view/software-engineer-900000005/?refId=mock-5','Software engineering with Python, Docker and REST API.'],
  ['Senior Backend Engineer','Platform Co','İstanbul','https://www.linkedin.com/jobs/view/900000006/?trackingId=mock-6','Senior backend role using Python and PostgreSQL.'],
  ['Sales Specialist','Revenue Co','Ankara','https://www.linkedin.com/jobs/view/900000007/?refId=mock-7','Sales and account growth.'],
  ['Customer Support Specialist','Service Co','Remote','https://www.linkedin.com/jobs/view/900000008/?trackingId=mock-8','Customer support for a software product.']
].map(([title,company,location,url,description]) => ({title,company,location,url,description}));
const text = jobs.map(j => `${j.title} | ${j.company} | ${j.location} | ${j.url}`).join('\n');
const html = jobs.map(j => `<a href="${j.url}">${j.title}</a><span>${j.company}</span><span>${j.location}</span>`).join('');
return [{json:{is_mock:true,mock_label:'LINKEDIN_JOB_ALERT_TEST_ONLY',subject:'Mock LinkedIn Job Alert',text,html,jobs}}];

const email = $json;
if (Array.isArray(email.jobs)) return email.jobs.map(job => ({json:{...job,is_mock:email.is_mock===true,mock_label:email.mock_label||null}}));
const text = String(email.text || email.textPlain || email.body || '');
const html = String(email.html || email.textHtml || '');
const rows = [];
for (const line of text.split(/\r?\n/)) {
  const parts = line.split('|').map(v => v.trim());
  if (parts.length >= 4 && /https:\/\/(?:www\.)?linkedin\.com\/jobs\/view\//i.test(parts[3])) rows.push({title:parts[0],company:parts[1],location:parts[2],url:parts[3],description:''});
}
if (!rows.length) {
  const anchors = [...html.matchAll(/<a[^>]+href=["']([^"']*linkedin\.com\/jobs\/view\/[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)];
  for (const match of anchors) rows.push({title:match[2].replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim(),company:'Unknown',location:'',url:match[1].replace(/&amp;/g,'&'),description:''});
}
return rows.map(job => ({json:{...job,is_mock:false,mock_label:null}}));

const raw = String($json.url || '').trim();
const idMatch = raw.match(/linkedin\.com\/jobs\/view\/[^?#]*?(\d+)(?:[/?#]|$)/i);
const queryMatch = raw.match(/[?&]currentJobId=(\d+)/i);
const external = idMatch?.[1] || queryMatch?.[1] || null;
const pathMatch = raw.match(/https:\/\/(?:www\.)?linkedin\.com(\/jobs\/view\/[^?#]+)/i);
const canonical = external ? `https://www.linkedin.com/jobs/view/${external}/` : pathMatch ? `https://www.linkedin.com${pathMatch[1].replace(/\/+$/,'')}/` : raw;
const title=String($json.title||'').trim(), description=String($json.description||'').trim();
const combined=`${title} ${description}`;
const exp=[...new Set(combined.match(/\b(?:(?:minimum(?:\s+of)?|at\s+least)\s+)?\d+\s*(?:\+|[-–—]\s*\d+)?\s*(?:years?|yrs?)\b/gi)||[])].join('; ');
const role=/\b(?:machine learning engineer|ml engineer|ai engineer|artificial intelligence engineer|junior ai engineer|junior machine learning engineer|data scientist|junior data scientist)\b/i.test(title)?'ai_ml':/\b(?:data engineer|junior data engineer|analytics engineer|data analyst|junior data analyst|business intelligence|bi developer|etl developer|data platform engineer)\b/i.test(title)?'data':/\b(?:python developer|python engineer|backend developer|backend engineer|back-end developer|back-end engineer|fastapi developer)\b/i.test(title)?'backend':/\b(?:software engineer|software developer|junior software engineer|junior software developer|graduate software engineer)\b/i.test(title)?'software':'unknown';
return {json:{title,company:String($json.company||'Unknown').trim(),city:String($json.location||'').trim()||null,work_model:/remote/i.test(combined+' '+($json.location||''))?'Remote':'On-site/Unknown',source:'LinkedIn',source_url:canonical,external_job_id:external,description:description||null,posted_at:null,career_level:/\b(junior|entry[\s-]?level|graduate|new[\s-]?grad|trainee|intern(?:ship)?|associate)\b/i.test(title)?'junior':'unknown',experience_text:exp,role_category:role,is_mock:$json.is_mock===true,mock_label:$json.mock_label||null}};
